const addFile = () => {
  const id = nextId();
  setFiles((f) => [...f, { id, name, kb, progress: 0, status: "uploading" }]);
  const iv = setInterval(() => {
    setFiles((f) => f.map((x) => {
      if (x.id !== id) return x;
      const p = Math.min(100, x.progress + 10 + Math.random() * 16);
      if (p >= 100) { clearInterval(iv); return { ...x, progress: 100, status: "done" }; }
      return { ...x, progress: p };
    }));
  }, 220);
};

