// Toast — requestAnimationFrame progress, pause on hover
function Toast({ t, onClose }) {
  const duration = t.duration ?? 5000;
  const [pct, setPct] = useState(100);
  const start = useRef(0), elapsed = useRef(0), raf = useRef(0), paused = useRef(false);

  useEffect(() => {
    if (duration === 0) return;                  // 0 = sticky (no auto-dismiss)
    const tick = (now) => {
      if (paused.current) { raf.current = requestAnimationFrame(tick); return; }
      if (!start.current) start.current = now;
      const e = elapsed.current + (now - start.current);
      const p = Math.max(0, 100 - (e / duration) * 100);
      setPct(p);
      p <= 0 ? onClose(t.id) : (raf.current = requestAnimationFrame(tick));
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, []);

  const onEnter = () => { paused.current = true; elapsed.current += performance.now() - start.current; start.current = 0; };
  const onLeave = () => { paused.current = false; };
  // … bar: <div style={{ width: pct + "%" }} className={"h-full " + tn.bar} /> …
}

// Solid tooltip — hover + focus, open delay, arrow
function Tooltip({ label, side = "top", delay = 130, children }) {
  const [open, setOpen] = useState(false);
  const t = useRef(null);
  const show = () => { clearTimeout(t.current); t.current = setTimeout(() => setOpen(true), delay); };
  const hide = () => { clearTimeout(t.current); setOpen(false); };
  const wrap = {
    top:    "bottom-full left-1/2 -translate-x-1/2 mb-2",
    bottom: "top-full left-1/2 -translate-x-1/2 mt-2",
    left:   "right-full top-1/2 -translate-y-1/2 mr-2",
    right:  "left-full top-1/2 -translate-y-1/2 ml-2",
  }[side];
  return (
    <span className="relative inline-flex"
      onMouseEnter={show} onMouseLeave={hide} onFocus={show} onBlur={hide}>
      {children}
      <span role="tooltip"
        className={"pointer-events-none absolute z-30 whitespace-nowrap rounded-md bg-foreground px-2.5 py-1.5 " +
          "text-[12px] font-medium text-background shadow-md transition-all duration-150 " + wrap +
          (open ? " opacity-100 scale-100" : " opacity-0 scale-95")}>
        {label}
      </span>
    </span>
  );
}

