/* ============================================================================
   @gntik-ai/tokens · tailwind.css — Tailwind v4 bridge over brand.css
   ----------------------------------------------------------------------------
   Import once, after `@import "tailwindcss";`. It maps every brand token to a
   Tailwind theme variable, so `bg-primary`, `text-muted-foreground`,
   `border-border/60` or `bg-primary/14` resolve to the active theme.
   brand.css stays the single source of truth: no value is defined here.
   Themes switch by class on <html>: "" (light) · "dark" · "high_contrast".
   ============================================================================ */
@import "./brand.css";
@import "./pairing.css";
@import "./motion.css";
@import "./density.css";

@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));
  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));
  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));
  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));
  --color-chrome: hsl(var(--chrome));
  --color-brand-secondary: hsl(var(--brand-secondary));
  --color-brand-accent: hsl(var(--brand-accent));
  --color-success: hsl(var(--success));
  --color-warning: hsl(var(--warning));
  --color-info: hsl(var(--info));
  --color-category-rose: hsl(var(--category-rose));
  --color-category-violet: hsl(var(--category-violet));
  --color-category-amber: hsl(var(--category-amber));
  --color-category-cyan: hsl(var(--category-cyan));
  --color-primary-text: hsl(var(--primary-text));
  --color-success-text: hsl(var(--success-text));
  --color-warning-text: hsl(var(--warning-text));
  --color-destructive-text: hsl(var(--destructive-text));
  --color-focus-ring: hsl(var(--focus-ring));
  --color-primary-chip-text: hsl(var(--primary-chip-text));
  --color-success-chip-text: hsl(var(--success-chip-text));
  --color-warning-chip-text: hsl(var(--warning-chip-text));
  --color-destructive-chip-text: hsl(var(--destructive-chip-text));
}

/* Radius, shadow and font scales: brand.css declares --radius-*, --shadow-*
   and --font-* unlayered, so they win over Tailwind's defaults of the same
   name. These inline aliases make the utilities (including bare `rounded`
   and `shadow`, and a width-less `ring`) read the brand variables, keeping
   the meaning the kit had under Tailwind v3. */
@theme inline {
  --radius: var(--radius);
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --shadow: var(--shadow-md);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --default-ring-width: 3px;
  --default-ring-color: hsl(var(--ring) / 0.5);
  --spacing-18: 4.5rem;
}

/* Motion (motion.css): `ease-standard|emphasized|exit` come from the --ease-*
   theme namespace; Tailwind 4 has no duration namespace, so the three named
   durations are static utilities. The bare `transition*` utilities default to
   the brand duration and easing, so they collapse under reduced motion too. */
@theme inline {
  --ease-standard: var(--ease-standard);
  --ease-emphasized: var(--ease-emphasized);
  --ease-exit: var(--ease-exit);
  --default-transition-duration: var(--duration-fast);
  --default-transition-timing-function: var(--ease-standard);
}

@utility duration-fast {
  --tw-duration: var(--duration-fast);
  transition-duration: var(--duration-fast);
}
@utility duration-normal {
  --tw-duration: var(--duration-normal);
  transition-duration: var(--duration-normal);
}
@utility duration-slow {
  --tw-duration: var(--duration-slow);
  transition-duration: var(--duration-slow);
}

/* Density (density.css): static utilities over the per-density variables, so a
   control follows `data-density` on any ancestor. Comfortable values equal the
   kit's original classes (h-control = h-9, px-control = px-3.5, h-row = h-10…). */
@utility h-control-sm { height: var(--control-h-sm); }
@utility h-control { height: var(--control-h-md); }
@utility h-control-lg { height: var(--control-h-lg); }
@utility w-control-sm { width: var(--control-h-sm); }
@utility w-control { width: var(--control-h-md); }
@utility w-control-lg { width: var(--control-h-lg); }
@utility size-control-sm { width: var(--control-h-sm); height: var(--control-h-sm); }
@utility size-control { width: var(--control-h-md); height: var(--control-h-md); }
@utility size-control-lg { width: var(--control-h-lg); height: var(--control-h-lg); }
@utility px-control-sm { padding-inline: var(--control-px-sm); }
@utility px-control { padding-inline: var(--control-px-md); }
@utility px-control-lg { padding-inline: var(--control-px-lg); }
@utility px-field { padding-inline: var(--field-px); }
@utility ps-field { padding-inline-start: var(--field-px); }
@utility gap-tight { gap: var(--gap-tight); }
@utility h-item { height: var(--item-h); }
@utility h-tab { height: var(--tab-h); }
@utility h-chip { height: var(--chip-h); }
@utility h-token { height: var(--token-h); }
@utility h-row { height: var(--row-h); }
@utility py-cell { padding-block: var(--cell-py); }
@utility py-bar { padding-block: var(--bar-py); }
